for (let i = 0; i < 200; i++) {
    const base = coreRules[i % coreRules.length];
    pronunciationHints.push({
        title: base.title ,
        eng: base.eng,
        jpn: base.jpn
    });
}

// Automatically attach pronunciation hints to ALL current and future lessons
b1Curriculum.forEach((lesson, index) => {
    if (!lesson.pronunciation && pronunciationHints[index]) {
        lesson.pronunciation = pronunciationHints[index];
    }
});
